Absolutely. Here's how to extend the search to cover both recipe names and ingredients:

## Combined Search (TypeScript)

```typescript
interface SearchResult {
  recipe: Recipe;
  matchedOn: {
    title: boolean;
    ingredients: string[];  // matched ingredient names
  };
}

function searchRecipes(recipes: Recipe[], query: string): SearchResult[] {
  const normalized = query.toLowerCase().trim();

  return recipes
    .map(recipe => {
      const titleMatch = recipe.title.toLowerCase().includes(normalized);
      const ingredientMatches = recipe.ingredients
        .filter(ing => ing.name.toLowerCase().includes(normalized))
        .map(ing => ing.name);

      if (titleMatch || ingredientMatches.length > 0) {
        return {
          recipe,
          matchedOn: {
            title: titleMatch,
            ingredients: ingredientMatches
          }
        };
      }
      return null;
    })
    .filter((result): result is SearchResult => result !== null);
}

// "chicken" matches:
// - Recipe titled "Chicken Parmesan" (title match)
// - Recipe with "chicken breast" ingredient (ingredient match)
// - Recipe titled "Chicken Soup" with "chicken stock" (both match)
```

## SQL (PostgreSQL)

```sql
SELECT DISTINCT 
  r.*,
  r.title ILIKE '%' || $1 || '%' AS title_match,
  ARRAY_AGG(i.name) FILTER (WHERE i.name ILIKE '%' || $1 || '%') AS matched_ingredients
FROM recipes r
LEFT JOIN recipe_ingredients ri ON r.id = ri.recipe_id
LEFT JOIN ingredients i ON ri.ingredient_id = i.id
WHERE 
  r.title ILIKE '%' || $1 || '%'
  OR i.name ILIKE '%' || $1 || '%'
GROUP BY r.id
ORDER BY 
  (r.title ILIKE '%' || $1 || '%') DESC,  -- title matches first
  COUNT(i.id) FILTER (WHERE i.name ILIKE '%' || $1 || '%') DESC
```

## With Ranking/Relevance

```typescript
function searchRecipesRanked(recipes: Recipe[], query: string): SearchResult[] {
  const normalized = query.toLowerCase().trim();

  return recipes
    .map(recipe => {
      const titleMatch = recipe.title.toLowerCase().includes(normalized);
      const exactTitleMatch = recipe.title.toLowerCase() === normalized;
      const ingredientMatches = recipe.ingredients
        .filter(ing => ing.name.toLowerCase().includes(normalized))
        .map(ing => ing.name);

      // Calculate relevance score
      let score = 0;
      if (exactTitleMatch) score += 100;
      else if (titleMatch) score += 50;
      score += ingredientMatches.length * 10;

      if (score > 0) {
        return {
          recipe,
          matchedOn: { title: titleMatch, ingredients: ingredientMatches },
          score
        };
      }
      return null;
    })
    .filter((result): result is SearchResult & { score: number } => result !== null)
    .sort((a, b) => b.score - a.score);
}
```

## API Response

```json
{
  "query": "chicken",
  "results": [
    {
      "id": "1",
      "title": "Chicken Parmesan",
      "matchedOn": {
        "title": true,
        "ingredients": ["chicken breast"]
      }
    },
    {
      "id": "2", 
      "title": "Vegetable Stir Fry",
      "matchedOn": {
        "title": false,
        "ingredients": ["chicken stock"]
      }
    }
  ]
}
```

---

**Search behavior summary:**

| Query | Matches title | Matches ingredient |
|-------|--------------|-------------------|
| "chicken" | "Chicken Soup" | "chicken breast" |
| "soup" | "Tomato Soup" | - |
| "garlic" | "Garlic Bread" | "garlic cloves" |
| "stir" | "Beef Stir Fry" | - |

