Here's how to handle multi-ingredient search with AND/OR logic:

## TypeScript Implementation

```typescript
type MatchMode = 'all' | 'any';

interface MultiSearchOptions {
  queries: string[];
  mode: MatchMode;
  searchTitle?: boolean;
}

interface MultiSearchResult {
  recipe: Recipe;
  matchedIngredients: string[];
  matchedQueries: string[];  // which search terms were found
  matchPercentage: number;   // what % of queries matched
}

function searchRecipesMulti(
  recipes: Recipe[], 
  options: MultiSearchOptions
): MultiSearchResult[] {
  const { queries, mode, searchTitle = true } = options;
  const normalized = queries.map(q => q.toLowerCase().trim());

  return recipes
    .map(recipe => {
      const titleLower = recipe.title.toLowerCase();
      const ingredientNames = recipe.ingredients.map(i => i.name.toLowerCase());

      const matchedQueries = normalized.filter(query => {
        const inTitle = searchTitle && titleLower.includes(query);
        const inIngredients = ingredientNames.some(name => name.includes(query));
        return inTitle || inIngredients;
      });

      const matchedIngredients = recipe.ingredients
        .filter(ing => 
          normalized.some(q => ing.name.toLowerCase().includes(q))
        )
        .map(ing => ing.name);

      const matchPercentage = (matchedQueries.length / queries.length) * 100;

      // Apply match mode
      const passes = mode === 'all' 
        ? matchedQueries.length === queries.length
        : matchedQueries.length > 0;

      if (passes) {
        return {
          recipe,
          matchedIngredients,
          matchedQueries,
          matchPercentage
        };
      }
      return null;
    })
    .filter((r): r is MultiSearchResult => r !== null)
    .sort((a, b) => b.matchPercentage - a.matchPercentage);
}
```

## Usage Examples

```typescript
// AND: must have both chicken AND garlic
searchRecipesMulti(recipes, {
  queries: ['chicken', 'garlic'],
  mode: 'all'
});

// OR: has chicken OR garlic (or both)
searchRecipesMulti(recipes, {
  queries: ['chicken', 'garlic'],
  mode: 'any'
});

// Find recipes with 3 ingredients (ranked by match %)
searchRecipesMulti(recipes, {
  queries: ['chicken', 'garlic', 'lemon'],
  mode: 'any'
});
// Returns recipes matching 3/3 (100%), then 2/3 (67%), then 1/3 (33%)
```

## SQL (PostgreSQL)

```sql
-- AND: recipes with ALL ingredients
WITH search_terms AS (
  SELECT unnest(ARRAY['chicken', 'garlic']) AS term
),
matches AS (
  SELECT 
    r.id,
    r.title,
    st.term,
    bool_or(i.name ILIKE '%' || st.term || '%') AS matched
  FROM recipes r
  CROSS JOIN search_terms st
  LEFT JOIN recipe_ingredients ri ON r.id = ri.recipe_id
  LEFT JOIN ingredients i ON ri.ingredient_id = i.id
  GROUP BY r.id, r.title, st.term
)
SELECT id, title
FROM matches
GROUP BY id, title
HAVING bool_and(matched) = true;  -- all terms must match

-- OR with match percentage (ranked)
WITH search_terms AS (
  SELECT unnest(ARRAY['chicken', 'garlic', 'lemon']) AS term
),
matches AS (
  SELECT 
    r.id,
    st.term,
    bool_or(
      r.title ILIKE '%' || st.term || '%' 
      OR i.name ILIKE '%' || st.term || '%'
    ) AS matched
  FROM recipes r
  CROSS JOIN search_terms st
  LEFT JOIN recipe_ingredients ri ON r.id = ri.recipe_id
  LEFT JOIN ingredients i ON ri.ingredient_id = i.id
  GROUP BY r.id, st.term
)
SELECT 
  r.*,
  COUNT(*) FILTER (WHERE matched) AS terms_matched,
  ROUND(100.0 * COUNT(*) FILTER (WHERE matched) / COUNT(*)) AS match_pct
FROM recipes r
JOIN matches m ON r.id = m.id
GROUP BY r.id
HAVING COUNT(*) FILTER (WHERE matched) > 0
ORDER BY match_pct DESC, terms_matched DESC;
```

## API Design

```
GET /api/recipes/search?q=chicken,garlic&mode=all
GET /api/recipes/search?q=chicken,garlic,lemon&mode=any
```

Response:
```json
{
  "query": ["chicken", "garlic", "lemon"],
  "mode": "any",
  "results": [
    {
      "id": "1",
      "title": "Lemon Garlic Chicken",
      "matchedQueries": ["chicken", "garlic", "lemon"],
      "matchPercentage": 100
    },
    {
      "id": "2",
      "title": "Chicken Stir Fry",
      "matchedQueries": ["chicken", "garlic"],
      "matchPercentage": 67
    },
    {
      "id": "3",
      "title": "Garlic Bread",
      "matchedQueries": ["garlic"],
      "matchPercentage": 33
    }
  ]
}
```

---

**Summary of modes:**

| Mode | Query | Result |
|------|-------|--------|
| `all` | chicken, garlic | Only recipes with both |
| `any` | chicken, garlic | Recipes with either (ranked by match %) |

The `any` mode with percentage ranking is particularly useful for "I have these ingredients, what can I make?" scenarios.

