Here are optimization strategies from quick wins to advanced solutions:

## 1. Database Indexing (First Priority)

```sql
-- Basic indexes
CREATE INDEX idx_recipes_title_lower ON recipes (LOWER(title));
CREATE INDEX idx_ingredients_name_lower ON ingredients (LOWER(name));

-- PostgreSQL trigram index for partial matches (best for ILIKE)
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX idx_recipes_title_trgm ON recipes USING GIN (title gin_trgm_ops);
CREATE INDEX idx_ingredients_name_trgm ON ingredients USING GIN (name gin_trgm_ops);

-- Composite index for join queries
CREATE INDEX idx_recipe_ingredients_recipe_id ON recipe_ingredients (recipe_id);
CREATE INDEX idx_recipe_ingredients_ingredient_id ON recipe_ingredients (ingredient_id);
```

## 2. Denormalize Search Data

Create a dedicated search column to avoid joins:

```sql
-- Add search column to recipes table
ALTER TABLE recipes ADD COLUMN search_text TEXT;
ALTER TABLE recipes ADD COLUMN search_vector TSVECTOR;

-- Populate with title + all ingredients
UPDATE recipes r SET search_text = (
  SELECT r.title || ' ' || STRING_AGG(i.name, ' ')
  FROM recipe_ingredients ri
  JOIN ingredients i ON ri.ingredient_id = i.id
  WHERE ri.recipe_id = r.id
  GROUP BY r.id
);

-- Create full-text search vector
UPDATE recipes SET search_vector = to_tsvector('english', search_text);
CREATE INDEX idx_recipes_search_vector ON recipes USING GIN (search_vector);

-- Fast full-text query
SELECT * FROM recipes 
WHERE search_vector @@ plainto_tsquery('english', 'chicken garlic');
```

## 3. Application-Level Caching

```typescript
import { LRUCache } from 'lru-cache';

const searchCache = new LRUCache<string, MultiSearchResult[]>({
  max: 500,           // max entries
  ttl: 1000 * 60 * 5  // 5 minute TTL
});

function searchRecipesCached(options: SearchOptions): MultiSearchResult[] {
  const cacheKey = `${options.queries.sort().join(',')}_${options.mode}`;

  const cached = searchCache.get(cacheKey);
  if (cached) return cached;

  const results = searchRecipes(recipes, options);
  searchCache.set(cacheKey, results);
  return results;
}
```

## 4. Precomputed Search Index (In-Memory)

```typescript
class RecipeSearchIndex {
  private titleIndex: Map<string, Set<string>> = new Map();      // word -> recipe IDs
  private ingredientIndex: Map<string, Set<string>> = new Map(); // word -> recipe IDs
  private recipes: Map<string, Recipe> = new Map();

  constructor(recipes: Recipe[]) {
    for (const recipe of recipes) {
      this.recipes.set(recipe.id, recipe);
      this.indexRecipe(recipe);
    }
  }

  private indexRecipe(recipe: Recipe) {
    // Index title words
    const titleWords = this.tokenize(recipe.title);
    for (const word of titleWords) {
      if (!this.titleIndex.has(word)) {
        this.titleIndex.set(word, new Set());
      }
      this.titleIndex.get(word)!.add(recipe.id);
    }

    // Index ingredient words
    for (const ing of recipe.ingredients) {
      const words = this.tokenize(ing.name);
      for (const word of words) {
        if (!this.ingredientIndex.has(word)) {
          this.ingredientIndex.set(word, new Set());
        }
        this.ingredientIndex.get(word)!.add(recipe.id);
      }
    }
  }

  private tokenize(text: string): string[] {
    return text.toLowerCase().split(/\s+/).filter(w => w.length > 2);
  }

  search(queries: string[], mode: 'and' | 'or'): Recipe[] {
    const normalized = queries.map(q => q.toLowerCase());

    const matchSets = normalized.map(query => {
      const matches = new Set<string>();

      // Find all indexed words containing the query
      for (const [word, ids] of this.titleIndex) {
        if (word.includes(query)) {
          ids.forEach(id => matches.add(id));
        }
      }
      for (const [word, ids] of this.ingredientIndex) {
        if (word.includes(query)) {
          ids.forEach(id => matches.add(id));
        }
      }
      return matches;
    });

    // Combine based on mode
    let resultIds: Set<string>;
    if (mode === 'and') {
      resultIds = matchSets.reduce((a, b) => 
        new Set([...a].filter(id => b.has(id)))
      );
    } else {
      resultIds = matchSets.reduce((a, b) => 
        new Set([...a, ...b])
      );
    }

    return [...resultIds].map(id => this.recipes.get(id)!);
  }
}

// Build once at startup
const searchIndex = new RecipeSearchIndex(allRecipes);

// Queries are now O(1) lookups instead of O(n) scans
searchIndex.search(['chicken', 'garlic'], 'and');
```

## 5. Dedicated Search Engine (Large Scale)

For 100k+ recipes, use a purpose-built search engine:

```typescript
// Meilisearch example (fast, easy setup)
import { MeiliSearch } from 'meilisearch';

const client = new MeiliSearch({ host: 'http://localhost:7700' });

// Index recipes
await client.index('recipes').addDocuments(
  recipes.map(r => ({
    id: r.id,
    title: r.title,
    ingredients: r.ingredients.map(i => i.name).join(' ')
  }))
);

// Configure searchable attributes
await client.index('recipes').updateSearchableAttributes([
  'title',
  'ingredients'
]);

// Search (returns in ~50ms even with millions of docs)
const results = await client.index('recipes').search('chicken garlic');
```

---

## Performance Comparison

| Approach | Dataset Size | Query Time |
|----------|-------------|------------|
| Naive scan | 1k recipes | ~10ms |
| Naive scan | 100k recipes | ~500ms |
| DB with trigram index | 100k recipes | ~20ms |
| In-memory index | 100k recipes | ~5ms |
| Meilisearch | 1M recipes | ~50ms |

## Recommendation by Scale

| Recipes | Recommended Approach |
|---------|---------------------|
| < 1,000 | Simple filter, maybe cache |
| 1k - 10k | Database indexes + caching |
| 10k - 100k | Denormalized search column + full-text index |
| 100k+ | Dedicated search engine (Meilisearch, Elasticsearch) |

